{
  "findings": [
    {
      "check_id": "CKV_AWS_16",
      "title": "Ensure all data stored in the RDS is securely encrypted at rest",
      "resource": "aws_db_instance.levelup-rds",
      "severity": "MEDIUM",
      "explanation": "The RDS instance does not have encryption at rest enabled, which may expose sensitive data stored in the database."
    },
    {
      "check_id": "CKV_AWS_129",
      "title": "Ensure that respective logs of Amazon Relational Database Service (Amazon RDS) are enabled",
      "resource": "aws_db_instance.levelup-rds",
      "severity": "MEDIUM",
      "explanation": "The RDS instance does not have logging enabled, which may hinder auditing and troubleshooting capabilities."
    },
    {
      "check_id": "CKV_AWS_157",
      "title": "Ensure that RDS instances have Multi-AZ enabled",
      "resource": "aws_db_instance.levelup-rds",
      "severity": "MEDIUM",
      "explanation": "The RDS instance has Multi-AZ disabled, which may lead to downtime in case of an AZ failure."
    },
    {
      "check_id": "CKV_AWS_226",
      "title": "Ensure DB instance gets all minor upgrades automatically",
      "resource": "aws_db_instance.levelup-rds",
      "severity": "MEDIUM",
      "explanation": "The RDS instance does not have auto minor version upgrades enabled, which may prevent it from receiving important security patches and bug fixes."
    },
    {
      "check_id": "CKV2_AWS_60",
      "title": "Ensure RDS instance with copy tags to snapshots is enabled",
      "resource": "aws_db_instance.levelup-rds",
      "severity": "MEDIUM",
      "explanation": "The RDS instance does not have 'copy tags to snapshots' enabled, which may lead to loss of metadata during snapshot creation."
    },
    {
      "check_id": "CKV_AWS_293",
      "title": "Ensure that AWS database instances have deletion protection enabled",
      "resource": "aws_db_instance.levelup-rds",
      "severity": "MEDIUM",
      "explanation": "The RDS instance does not have deletion protection enabled, which may allow accidental deletion of the database instance."
    }
  ],
  "patched_code": "resource \"aws_db_instance\" \"levelup-rds\" {\n  identifier = \"${var.ENVIRONMENT}-levelup-rds\"\n  allocated_storage = var.LEVELUP_RDS_ALLOCATED_STORAGE\n  storage_type = \"gp2\"\n  engine = var.LEVELUP_RDS_ENGINE\n  engine_version = var.LEVELUP_RDS_ENGINE_VERSION\n  instance_class = var.DB_INSTANCE_CLASS\n  backup_retention_period = var.BACKUP_RETENTION_PERIOD\n  publicly_accessible = var.PUBLICLY_ACCESSIBLE\n  username = var.LEVELUP_RDS_USERNAME\n  password = var.LEVELUP_RDS_PASSWORD\n  vpc_security_group_ids = [aws_security_group.levelup-rds-sg.id]\n  db_subnet_group_name = aws_db_subnet_group.levelup-rds-subnet-group.name\n  multi_az = true\n  storage_encrypted = true\n  auto_minor_version_upgrade = true\n  copy_tags_to_snapshot = true\n  deletion_protection = true\n}",
  "fix_summary": "Enabled storage encryption, Multi-AZ, auto minor version upgrades, copy tags to snapshot, and deletion protection for the RDS instance."
}
